fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column from the input matrix
    // Preconditions:
    // - j < m
    // - input has n rows, each with length m
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        // Safety: input[i][j] is valid as per problem statement dimensions
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // For each column index j in input, get the column vector and collect these
    // columns as the rows of the output (i.e., transpose)
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}